/*
 * telemetry.h - builds the JSON documents defined in
 * docs/telemetry_protocol.md (schema_version 1).
 *
 * Invalid or missing measurements are emitted as JSON null, never as 0.
 * The sequence number counts telemetry packets generated by the STM32;
 * it increments even if a packet is later dropped because the UART TX
 * buffer is full, so the host can see the loss as a sequence gap.
 */
#ifndef TELEMETRY_H
#define TELEMETRY_H

#include <stddef.h>
#include <stdint.h>

#include "sensor_manager.h"

typedef struct {
    uint32_t telemetry_generated;
    uint32_t telemetry_dropped;     /* not queued: UART TX buffer full */
    uint32_t frames_dropped;        /* all frame kinds */
    uint32_t link_rx_frames;
    uint32_t link_rx_bad;           /* bad checksum / malformed */
    uint32_t link_rx_oversize;
    uint32_t link_rx_errors;        /* UART framing/noise errors */
    uint32_t link_rx_overflows;
    uint32_t i2c_errors;
    uint32_t i2c_recoveries;
    uint8_t  esp_link;              /* heartbeat seen within timeout */
    uint8_t  esp_wifi;
    uint8_t  esp_mqtt;
} telemetry_diag_t;

/* Returns the number of characters written (excluding NUL), 0 on overflow. */
size_t telemetry_build_sample(char *buf, size_t cap, uint32_t sequence, uint32_t now,
                              const imu_reading_t *imu, const baro_reading_t *baro,
                              float sea_level_hpa);

size_t telemetry_build_status(char *buf, size_t cap, uint32_t now,
                              const sensor_stats_t *ss, const telemetry_diag_t *d,
                              float sea_level_hpa);

size_t telemetry_build_event(char *buf, size_t cap, uint32_t now,
                             const char *event, const char *detail);

#endif /* TELEMETRY_H */
